  "Text-only generation: no Amazon images are scraped or uploaded. Results illustrate a generic style, not the exact branded product.": {
    "fr": "Génération à partir de texte uniquement : aucune image Amazon n’est extraite ni envoyée. Le résultat illustre un style générique, pas le produit de marque exact.",
    "ar": "إنشاء من النص فقط: لا تُستخرج صور Amazon ولا تُرفع. توضّح النتائج نمطًا عامًا وليست المنتج ذي العلامة التجارية نفسه.",
    "es": "Generación solo a partir de texto: no se extraen ni suben imágenes de Amazon. Los resultados ilustran un estilo genérico, no el producto de marca exacto."
  },
  "Generate Unbranded Studio Photo": {
    "fr": "Générer une photo studio sans marque",
    "ar": "إنشاء صورة ستوديو دون علامة تجارية",
    "es": "Generar foto de estudio sin marca"
  },
  "Image generation is unavailable. Configure GEMINI_API_KEY on the server, try again later, or copy the prompt and upload your own photo.": {
    "fr": "La génération d’image est indisponible. Configurez GEMINI_API_KEY sur le serveur, réessayez plus tard ou copiez le prompt et importez votre propre photo.",
    "ar": "إنشاء الصور غير متاح. اضبط GEMINI_API_KEY على الخادم أو حاول لاحقًا، أو انسخ التعليمات وارفع صورتك الخاصة.",
    "es": "La generación de imágenes no está disponible. Configura GEMINI_API_KEY en el servidor, inténtalo más tarde o copia la instrucción y sube tu propia foto."
  },
  "Representative AI-generated product image": {
    "fr": "Image produit représentative générée par IA",
    "ar": "صورة تمثيلية للمنتج مُنشأة بالذكاء الاصطناعي",
    "es": "Imagen representativa de producto generada por IA"
  },
  "Representative AI image — not the exact branded product.": {
    "fr": "Image IA représentative — pas le produit de marque exact.",
    "ar": "صورة تمثيلية بالذكاء الاصطناعي — ليست المنتج ذي العلامة التجارية نفسه.",
    "es": "Imagen representativa de IA — no es el producto de marca exacto."
  },
  "I reviewed this image for unwanted logos, text and recognizable brand designs before using it.": {
    "fr": "J’ai vérifié l’absence de logos, textes et designs de marque reconnaissables avant d’utiliser cette image.",
    "ar": "راجعت الصورة للتأكد من عدم وجود شعارات أو نصوص أو تصاميم تجارية مميزة قبل استخدامها.",
    "es": "He revisado esta imagen para detectar logotipos, texto y diseños de marca reconocibles antes de utilizarla."
  },
