  "Target tone and audience: ": {
    "fr": "Ton et public cible : ",
    "ar": "النبرة والجمهور المستهدف: ",
    "es": "Tono y público objetivo: "
  },
  "Use the supplied details as context. Keep claims specific and verifiable. Never invent prices, specs, testimonials, or results. Ask up to three focused questions if missing facts would materially change the draft. Otherwise use clearly marked placeholders and return the requested deliverables in order.": {
    "fr": "Réponds en français à partir des informations fournies. Formule des affirmations précises et vérifiables. N’invente aucun prix, aucune caractéristique, aucun témoignage ni aucun résultat. Pose jusqu’à trois questions ciblées si une information manquante change sensiblement le résultat. Sinon, indique clairement les éléments à compléter et rends les livrables dans l’ordre demandé.",
    "ar": "أجب باللغة العربية بالاعتماد على المعلومات المقدَّمة. اجعل الادعاءات محددة وقابلة للتحقق. لا تخترع أسعارًا أو مواصفات أو شهادات عملاء أو نتائج. اطرح ما يصل إلى ثلاثة أسئلة محددة إذا كانت المعلومات الناقصة ستغيّر المسودة بصورة جوهرية. وإلا، حدّد مواضع البيانات الناقصة بوضوح وقدّم المطلوب بالترتيب.",
    "es": "Utiliza los datos proporcionados como contexto. Mantén las afirmaciones concretas y verificables. Nunca inventes precios, especificaciones, testimonios ni resultados. Haz hasta tres preguntas concretas si la información que falta cambia sustancialmente el borrador. De lo contrario, utiliza marcadores claros y entrega los resultados solicitados en orden."
  },
