  "Check the exact model, image license, attribution and brand permissions. Unsplash searches lifestyle photos; results are not guaranteed to show your exact product.": {
    "fr": "Vérifiez le modèle exact, la licence, les crédits et les autorisations de la marque. Unsplash recherche des photos d’ambiance, sans garantir le modèle exact.",
    "ar": "تحقق من الطراز الدقيق وترخيص الصورة ومتطلبات نسبها وأذونات العلامة. يبحث Unsplash عن صور أسلوب الحياة ولا يضمن عرض المنتج نفسه.",
    "es": "Comprueba el modelo exacto, la licencia, la atribución y los permisos de marca. Unsplash busca fotos de estilo de vida; los resultados no garantizan mostrar tu producto exacto."
  },
