  "Copy / Share Link": {
    "fr": "Copier / partager le lien",
    "ar": "نسخ الرابط أو مشاركته",
    "es": "Copiar / compartir enlace"
  },
  "How SellPostly Works": {
    "fr": "Comment fonctionne SellPostly",
    "ar": "كيف يعمل SellPostly",
    "es": "Cómo funciona SellPostly"
  },
  "SellPostly is strictly a SaaS storefront software provider. Independent shops do not represent the SellPostly brand. Products, fulfillment, payments and direct transactions are solely between the buyer and the independent seller.": {
    "fr": "SellPostly fournit uniquement un logiciel de boutique en mode SaaS. Les boutiques indépendantes ne représentent pas la marque SellPostly. Les produits, la livraison, les paiements et les transactions directes relèvent exclusivement de l’acheteur et du vendeur indépendant.",
    "ar": "SellPostly مزوّد برمجيات متاجر بنظام SaaS فقط. لا تمثّل المتاجر المستقلة علامة SellPostly. المنتجات والتنفيذ والمدفوعات والمعاملات المباشرة تتم حصرًا بين المشتري والبائع المستقل.",
    "es": "SellPostly es exclusivamente un proveedor de software de tiendas en modalidad SaaS. Las tiendas independientes no representan a SellPostly. Los productos, la entrega, los pagos y las transacciones directas son responsabilidad del comprador y del vendedor independiente."
  },
  "Seller Payment Methods": {
    "fr": "Moyens de paiement du vendeur",
    "ar": "طرق دفع البائع",
    "es": "Métodos de pago del vendedor"
  },
  "Enabled payment details are public to buyers. Never enter card numbers, security codes or expiry dates.": {
    "fr": "Les coordonnées activées sont publiques pour les acheteurs. Ne saisissez jamais de numéro de carte, de code de sécurité ou de date d’expiration.",
    "ar": "تفاصيل الدفع المفعّلة متاحة للمشترين. لا تدخل أرقام البطاقات أو رموز الأمان أو تواريخ الانتهاء مطلقًا.",
    "es": "Los datos de pago habilitados son públicos para los compradores. Nunca introduzcas números de tarjeta, códigos de seguridad ni fechas de caducidad."
  },
